/**
 * 运行时上下文保持内联，避免发布包依赖未随 main.js 分发的本地模块。
 * 任务查询规范与 `core/task-query-context.js` 共用同一合同。
 */
function noriaNormalizeVaultPath(raw) {
  return String(raw || "")
    .trim()
    .replace(/\\/g, "/")
    .replace(/^\/+/, "");
}

function noriaNormalizeEmbeddedPath(raw) {
  const p = noriaNormalizeVaultPath(raw);
  return p.startsWith(NORIA_PLUGIN_VAULT_PREFIX)
    ? p.slice(NORIA_PLUGIN_VAULT_PREFIX.length)
    : p;
}

function noriaReadEmbeddedSource(rawPath) {
  const key = noriaNormalizeEmbeddedPath(rawPath);
  if (!key) return "";
  return Object.prototype.hasOwnProperty.call(NORIA_EMBEDDED_SOURCES || {}, key)
    ? String(NORIA_EMBEDDED_SOURCES[key] || "")
    : "";
}

function noriaRuntimeSourceFallbackPath(rawPath) {
  const key = noriaNormalizeEmbeddedPath(rawPath);
  if (!/^(views|core|config)\//.test(key)) return "";
  return `src/runtime/${key}`;
}

function createNoriaViewContext(app, plugin, options = {}) {
  const container = options.container;
  const explicitOrigin = noriaNormalizeVaultPath(options?.originFile ?? "");
  const activeOrigin = noriaNormalizeVaultPath(app?.workspace?.getActiveFile?.()?.path || "");
  const originCandidates = [explicitOrigin, activeOrigin]
    .filter(Boolean)
    .filter((v, i, arr) => arr.indexOf(v) === i);
  const originFile = originCandidates[0] || "";

  const dom = {
    el(tag, text, opts = {}) {
      const o = { ...(opts || {}) };
      const parent = o.container || container;
      delete o.container;
      const attr = o.attr;
      if (attr) delete o.attr;

      const str = text == null ? "" : String(text);
      const htmlLike = typeof text === "string" && /<\s*[a-z!/]/i.test(text);

      if (htmlLike) {
        const el = parent.createEl(tag, o);
        if (attr) Object.entries(attr).forEach(([k, v]) => el.setAttribute(k, String(v)));
        el.innerHTML = str;
        return el;
      }

      if (text != null && typeof text === "object" && !(text instanceof String)) {
        const el = parent.createEl(tag, o);
        if (attr) Object.entries(attr).forEach(([k, v]) => el.setAttribute(k, String(v)));
        const pathVal = text.path;
        const display = text.display;
        if (pathVal) {
          el.createEl("a", {
            text: display || pathVal,
            href: pathVal.endsWith(".md") ? pathVal : `${pathVal}.md`,
            cls: "internal-link"
          });
        } else {
          el.setText(str || JSON.stringify(text));
        }
        return el;
      }

      const el = parent.createEl(tag, {
        ...o,
        text: str === "" ? undefined : str
      });
      if (attr) Object.entries(attr).forEach(([k, v]) => el.setAttribute(k, String(v)));
      return el;
    },
    span(text, opts) {
      return this.el("span", text, opts);
    },
    paragraph(text, opts) {
      return this.el("p", text, opts);
    }
  };

  const ioLoadFallback = async (path) => {
    const t = await plugin.loadTextFromVault(noriaNormalizeVaultPath(path));
    return t ? t : undefined;
  };

  const io = {
    load: ioLoadFallback,
    normalize: (path) => noriaNormalizeVaultPath(path),
    csv: async () => undefined
  };

  const parseQueryRoots = (query) => {
    const raw = String(query == null ? "" : query).trim();
    if (!raw) return [];
    const roots = [];
    raw.replace(/"([^"]+)"/g, (_, root) => {
      const normalized = noriaNormalizeVaultPath(root);
      if (normalized && !roots.includes(normalized)) roots.push(normalized);
      return "";
    });
    if (!roots.length) {
      const normalized = noriaNormalizeVaultPath(raw.replace(/^'+|'+$/g, ""));
      if (normalized) roots.push(normalized);
    }
    return roots;
  };
  const pagesForRoots = (roots) => {
    try {
      if (!roots.length) return [];
      return plugin.filesUnderRoots(roots, [".md"])
        .filter((file) => !plugin.isReviewNotePath?.(file?.path || ""))
        .map((file) => plugin.pageFactFromFile(file));
    } catch (_) {
      return [];
    }
  };
  const pageForPath = (pathText) => plugin.pageFactForPath(pathText);
  const currentPage = () => {
    for (const ori of originCandidates) {
      const page = pageForPath(ori);
      if (page) return page;
    }
    return undefined;
  };

  return {
    container,
    mount: container,
    app,
    bridge: globalThis.__noriaRuntimeBridge || plugin.buildRuntimeBridgeConfig?.() || {},
    sourcePath: originFile,
    props: options.props || {},
    readText: (path) => ioLoadFallback(path),
    createEl: dom.el.bind(dom),
    filesForScope: (scopeId) => plugin.filesForScope(scopeId),
    filesForManagedPath: (pathKey) => plugin.filesForManagedPath(pathKey),
    page: pageForPath,
    current: currentPage,
    io,
    pages: (query) => pagesForRoots(parseQueryRoots(query)),
    pagePaths: (query) => pagesForRoots(parseQueryRoots(query)).map((page) => page?.file?.path).filter(Boolean),
    array: (raw) => Array.isArray(raw) ? raw : Array.from(raw || []),
    isArray: (raw) => Array.isArray(raw),
    isDataArray: () => false,
    el: dom.el.bind(dom),
    span: dom.span.bind(dom),
    paragraph: dom.paragraph.bind(dom)
  };
}

const NORIA_DEFAULT_TASK_QUERY_POLICY = {
  includeTimelineInMonth: false,
  includeCancelled: true,
  excludeOverdueTimeline: true
};
const NORIA_DEFAULT_TASK_EXCLUDE_TAGS = ["#habit"];

function normalizeTaskFilterTag(raw) {
  let tag = String(raw || "").trim();
  if (!tag) return "";
  if (!tag.startsWith("#")) tag = `#${tag.replace(/^#+/, "")}`;
  return tag;
}

function normalizeTaskFilterTagList(raw) {
  const source = Array.isArray(raw) ? raw : (typeof raw === "string" ? raw.split(",") : []);
  const out = [];
  for (const item of source) {
    const tag = normalizeTaskFilterTag(item);
    if (!tag) continue;
    if (!out.some((x) => x.toLowerCase() === tag.toLowerCase())) out.push(tag);
  }
  return out;
}

function getTaskQueryContext(settings) {
  const s = settings && typeof settings === "object" ? settings : {};
  const taskTagFilter = s.taskTagFilter && typeof s.taskTagFilter === "object"
    ? s.taskTagFilter
    : { includeTags: [], excludeTags: NORIA_DEFAULT_TASK_EXCLUDE_TAGS };
  const includeTags = normalizeTaskFilterTagList(taskTagFilter.includeTags);
  const excludeTags = normalizeTaskFilterTagList(taskTagFilter.excludeTags);

  const taskQueryPolicy = {
    ...NORIA_DEFAULT_TASK_QUERY_POLICY,
    ...(s.taskQueryPolicy && typeof s.taskQueryPolicy === "object" ? s.taskQueryPolicy : {})
  };

  const taskTypeFilter = {
    showDone: true,
    showOverdue: true,
    showRecurring: true,
    showScheduled: true,
    ...(s.taskTypeFilter && typeof s.taskTypeFilter === "object" ? s.taskTypeFilter : {})
  };

  const wrapperTaskFilter =
    s.wrapperTaskFilter && typeof s.wrapperTaskFilter === "object" ? { ...s.wrapperTaskFilter } : {};

  return {
    taskTagFilter: { includeTags, excludeTags },
    taskQueryPolicy,
    taskTypeFilter,
    wrapperTaskFilter
  };
}

