function stablePomodoroHash(value) {
  const text = String(value || "");
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h.toString(36);
}

function normalizePomodoroTaskKey(key) {
  const k = String(key || "").trim();
  if (!k) return "";
  if (/^zp_[a-z0-9]+$/i.test(k)) return k;
  return `zp_${stablePomodoroHash(`legacy:${k}`)}`;
}

