function noriaNormalizeWeatherSecretName(value) {
  const candidate = String(value || "").trim();
  return /^[a-z0-9-]+$/.test(candidate)
    ? candidate
    : NORIA_DEFAULT_WEATHER.qweatherSecretName;
}

function noriaNormalizeQweatherApiHost(value) {
  const host = String(value || "")
    .trim()
    .replace(/^https?:\/\//i, "")
    .replace(/\/.*$/, "")
    .toLowerCase();
  return /^[a-z0-9.-]+(?::\d+)?$/.test(host) ? host : "";
}

