    if (next.manualZoomIndex != null) this.plugin.settings.timelineView.manualZoomIndex = next.manualZoomIndex;
    if (next.manualOverviewZoomIndex != null) this.plugin.settings.timelineView.manualOverviewZoomIndex = next.manualOverviewZoomIndex;
