  renderMocEntrySettings(containerEl) {
    const manager = containerEl.createDiv({ cls: "noria-moc-entry-manager" });
    const entries = this.plugin.getMocEntriesForDashboard();
    const commit = async (nextEntries, reason) => {
      await this.plugin.setMocEntries(nextEntries, { reason });
      this.display();
    };
    let addInput = null;
    const addEntry = async () => {
      const path = this.plugin.normalizePath(addInput?.value || "").replace(/^\/+/, "");
      if (!path) {
        addInput?.focus?.();
        return;
      }
      await commit([...entries, { path, color: "" }], "settings:moc-entry-add");
    };

    const head = new obsidian.Setting(manager)
      .setName(this.t("settings.home.mocEntryPaths"))
      .setDesc(this.t("settings.home.mocEntryPathsDesc"))
      .addText((text) => {
        addInput = text.inputEl;
        text.setPlaceholder("05_MOC/示例·MOC.md");
        text.inputEl?.setAttribute?.("aria-label", this.t("settings.home.mocEntryPath"));
        this.plugin.attachHomeWidgetSourceSuggest(text.inputEl, () => "moc");
        text.inputEl?.addEventListener?.("keydown", (event) => {
          if (event.key !== "Enter") return;
          event.preventDefault();
          void addEntry();
        });
      })
      .addButton((button) => {
        if (typeof button.setIcon === "function") button.setIcon("plus");
        else button.setButtonText("+");
        if (typeof button.setTooltip === "function") button.setTooltip(this.t("settings.home.mocEntryAdd"));
        button.onClick(addEntry);
      });
    head.settingEl?.addClass?.("noria-moc-entry-manager-head");

    if (!entries.length) {
      manager.createDiv({ cls: "noria-moc-entry-empty", text: this.t("settings.home.mocEntryEmpty") });
      return;
    }

    entries.forEach((entry, index) => {
      const path = String(entry.path || "");
      const file = path ? this.app?.vault?.getAbstractFileByPath?.(path) : null;
      const leaf = path.split("/").pop() || path;
      const title = leaf.replace(/\.(?:md|canvas)$/i, "") || path;
      const status = this.t(file ? "settings.home.mocEntryReady" : "settings.home.mocEntryMissing");
      const row = new obsidian.Setting(manager)
        .setName(title)
        .setDesc(`${path} · ${status}`);
      row.settingEl?.addClass?.("noria-moc-entry-row");
      row.settingEl?.setAttribute?.("data-noria-moc-entry-path", path);
      row.settingEl?.setAttribute?.("data-noria-moc-entry-state", file ? "ready" : "missing");

      row.addText((text) => {
        let draft = path;
        let committing = false;
        const saveDraft = async () => {
          const nextPath = this.plugin.normalizePath(draft || "").replace(/^\/+/, "");
          if (committing || !nextPath || nextPath === path) return;
          committing = true;
          const next = entries.map((item, itemIndex) => itemIndex === index ? { ...item, path: nextPath } : item);
          await commit(next, "settings:moc-entry-path");
        };
        text
          .setPlaceholder(this.t("settings.home.mocEntryPath"))
          .setValue(path)
          .onChange((value) => { draft = value; });
        text.inputEl?.setAttribute?.("aria-label", `${this.t("settings.home.mocEntryPath")}: ${title}`);
        text.inputEl?.addEventListener?.("blur", () => { void saveDraft(); });
        text.inputEl?.addEventListener?.("keydown", (event) => {
          if (event.key !== "Enter") return;
          event.preventDefault();
          text.inputEl?.blur?.();
        });
        this.plugin.attachHomeWidgetSourceSuggest(text.inputEl, () => "moc");
      });

      if (typeof row.addColorPicker === "function") {
        row.addColorPicker((picker) => {
          picker
            .setValue(entry.color || "#8b5cf6")
            .onChange(async (value) => {
              const next = entries.map((item, itemIndex) => itemIndex === index ? { ...item, color: value } : item);
              await commit(next, "settings:moc-entry-color");
            });
          picker.colorPickerEl?.setAttribute?.("aria-label", `${this.t("settings.home.mocEntryColor")}: ${title}`);
        });
      }

      row
        .addButton((button) => {
          if (typeof button.setIcon === "function") button.setIcon("arrow-up");
          else button.setButtonText("↑");
          const label = this.t("settings.home.mocEntryMoveUp");
          if (typeof button.setTooltip === "function") button.setTooltip(label);
          this.decorateSettingsManagerIconButton(button.buttonEl, "move-up", label);
          if (typeof button.setDisabled === "function") button.setDisabled(index === 0);
          button.onClick(async () => {
            if (index === 0) return;
            const next = [...entries];
            [next[index - 1], next[index]] = [next[index], next[index - 1]];
            await commit(next, "settings:moc-entry-order");
          });
        })
        .addButton((button) => {
          if (typeof button.setIcon === "function") button.setIcon("arrow-down");
          else button.setButtonText("↓");
          const label = this.t("settings.home.mocEntryMoveDown");
          if (typeof button.setTooltip === "function") button.setTooltip(label);
          this.decorateSettingsManagerIconButton(button.buttonEl, "move-down", label);
          if (typeof button.setDisabled === "function") button.setDisabled(index === entries.length - 1);
          button.onClick(async () => {
            if (index >= entries.length - 1) return;
            const next = [...entries];
            [next[index], next[index + 1]] = [next[index + 1], next[index]];
            await commit(next, "settings:moc-entry-order");
          });
        })
        .addButton((button) => {
          if (typeof button.setIcon === "function") button.setIcon("trash-2");
          else button.setButtonText("-");
          const label = this.t("settings.home.mocEntryRemove");
          if (typeof button.setTooltip === "function") button.setTooltip(label);
          this.decorateSettingsManagerIconButton(button.buttonEl, "remove", label);
          button.onClick(async () => {
            await commit(entries.filter((_item, itemIndex) => itemIndex !== index), "settings:moc-entry-remove");
          });
        });
    });
  }

